SELECT CASE WHEN budget >= 4130000 THEN 'high' WHEN budget >= 1931000 THEN 'mid' ELSE 'low' END budget_bucket, dept_name, SUM(CASE WHEN location = 'Bangkok' THEN 1 ELSE 0 END) bangkok_count, MIN(budget) min_budget, SORT_ARRAY(COLLECT_SET(dept_name)) dept_name_list FROM departments GROUP BY CASE WHEN budget >= 4130000 THEN 'high' WHEN budget >= 1931000 THEN 'mid' ELSE 'low' END, dept_name HAVING COUNT(*) < 3
